{"success": true, "data": {"stdout": "#!/usr/bin/env python3
"""Classify paraphrases into diversity tiers based on metrics.

Input:  diversity_metrics.json from diversity_metrics.py
Output: JSON with tier assignments and distribution statistics.

Tier definitions (based on openvla_embed_sim):
  Tier-1 (trivial):  embed_sim > 0.95
  Tier-2 (moderate): 0.80 < embed_sim <= 0.95
  Tier-3 (deep):     embed_sim <= 0.80
"""

import argparse
import json
import os
from collections import Counter
from pathlib import Path


def classify_tier(embed_sim: float) -> int:
    if embed_sim > 0.95:
        return 1
    elif embed_sim > 0.80:
        return 2
    else:
        return 3


def _pick_embed_key(per_task: dict) -> str:
    """Pick the embed_sim key: prefer openvla, fall back to minilm, then legacy."""
    sample_para = next(iter(per_task.values()))["paraphrases"][0]
    for key in ("openvla_embed_sim", "minilm_embed_sim", "embed_sim"):
        if key in sample_para:
            return key
    raise KeyError("No embed_sim field found in metrics")


def run_tier_classification(metrics: dict) -> dict:
    per_task = metrics["per_task"]
    embed_key = _pick_embed_key(per_task)

    classified = {}
    all_tiers = []
    tier_examples = {1: [], 2: [], 3: []}

    for task_id, task_data in per_task.items():
        task_classified = []
        for para in task_data["paraphrases"]:
            tier = classify_tier(para[embed_key])
            entry = {**para, "tier": tier}
            task_classified.append(entry)
            all_tiers.append(tier)

            if len(tier_examples[tier]) < 3:
                tier_examples[tier].append({
                    "task_id": task_id,
                    "original": task_data["original"],
                    "paraphrase": para["text"],
                    "embed_sim": para[embed_key],
                    "embed_key_used": embed_key,
                    "1_bleu": para["1_bleu"],
                })

        classified[task_id] = {
            "original": task_data["original"],
            "paraphrases": task_classified,
        }

    total = len(all_tiers)
    tier_counts = Counter(all_tiers)
    distribution = {}
    for t in [1, 2, 3]:
        distribution[f"tier_{t}"] = {
            "count": tier_counts.get(t, 0),
            "percentage": tier_counts.get(t, 0) / total * 100 if total > 0 else 0,
        }

    tier2_plus_pct = (tier_counts.get(2, 0) + tier_counts.get(3, 0)) / total * 100 if total > 0 else 0

    return {
        "per_task": classified,
        "distribution": distribution,
        "tier2_plus_percentage": tier2_plus_pct,
        "total_paraphrases": total,
        "embed_model_used": embed_key,
        "examples": {f"tier_{t}": tier_examples[t] for t in [1, 2, 3]},
    }


def main():
    parser = argparse.ArgumentParser(description="Classify paraphrases into diversity tiers")
    parser.add_argument("--input", required=True, help="diversity_metrics.json from diversity_metrics.py")
    parser.add_argument("--output-dir", default="./results/phase0", help="Output directory")
    args = parser.parse_args()

    os.makedirs(args.output_dir, exist_ok=True)

    with open(args.input) as f:
        metrics = json.load(f)

    results = run_tier_classification(metrics)

    out_path = Path(args.output_dir) / "tier_classification.json"
    with open(out_path, "w") as f:
        json.dump(results, f, indent=2)

    print(f"\n{'='*50}")
    print(f"Tier Classification ({results['total_paraphrases']} paraphrases)")
    print(f"  Embedding model: {results['embed_model_used']}")
    print(f"{'='*50}")
    labels = {"tier_1": "Tier-1 (trivial)", "tier_2": "Tier-2 (moderate)", "tier_3": "Tier-3 (deep)"}
    for tier_name, stats in results["distribution"].items():
        print(f"  {labels[tier_name]:25s}: {stats['count']:4d}  ({stats['percentage']:.1f}%)")
    print(f"  {'Tier-2+ total':25s}:       ({results['tier2_plus_percentage']:.1f}%)")

    print(f"\nExamples:")
    for tier in [1, 2, 3]:
        exs = results["examples"][f"tier_{tier}"]
        if exs:
            print(f"\n  Tier-{tier}:")
            for ex in exs[:2]:
                print(f"    orig: \"{ex['original']}\"")
                print(f"    para: \"{ex['paraphrase']}\"  (sim={ex['embed_sim']:.3f})")

    print(f"\nSaved to {out_path}")


if __name__ == "__main__":
    main()
